// Placeholder art for carousel thumbnails, inlined as data URIs so the
// compiled bundle is fully self-contained (no .png asset imports for the
// consumer's bundler to resolve). Ported from nova-chat-sdk
// src/assets/{desk,room,virtual}_placeholder.png +
// src/utils/resourcePlaceholder.ts (placeholderImageForType).

export const DESK_PLACEHOLDER =
	'data:image/png;base64,';

export const ROOM_PLACEHOLDER =
	'data:image/png;base64,';

export const VIRTUAL_PLACEHOLDER =
	'data:image/png;base64,';

export function placeholderImageForType(type?: string, opts?: { virtual?: boolean }): string {
	if (opts?.virtual) return VIRTUAL_PLACEHOLDER;
	if (type === 'desk') return DESK_PLACEHOLDER;
	return ROOM_PLACEHOLDER;
}
